#!/usr/bin/env python3
"""Read-only current-cohort check; bundled helpers are independently hash-bound.

The bundle is generated from the adjacent performance payload/current helpers.
It reads the retained pinned root package and existing installation only. It
does not install a runtime, stop a service, publish, or execute application PHP.
"""
import base64
import copy
import hashlib
import json
import os
from pathlib import Path
import re
import socket
import stat
import subprocess
import sys
import types

ROOT_REV = '1e651117deabb4c6935933ee424237d82bd316cb'
ROOT_SHA = '90d9dff5ff0fcadb4854f5f0dc2103dcfe8b9b25ef9922164fba1b6e690a03e9'
SEED = '11c739039e5c6320b3542d414682d755c7902790'
NATIVE_CHANGES = {
    'main.cjs': '1ae3aa1056918dc7a34271a2da914dd2b737aa01d7c9134cfe14f9ee253184c2',
    'dashboard.cjs': '57cd03e330d4748a4d20134a75308b59b2e59f1e9566a40d528cf4d4eb6c1381',
    'workspace-delta.cjs': '8ca4435ea30e443936d74c58f47722adc1f65e117976198808ab8c713438a40b',
}
# Generated bundle. Each tuple contains the original source SHA256 and base64.
BUNDLED_MODULES = {'payloads': ('c2352af7799d96104a48192b0fe221b770189041f258e495c85e3661e768d459', ''), 'current': ('5d0d6f4fb6d3322b792d586d54f3536546b427007a8d514f2fa30da8e022b775', '')}
PUBLIC_FIELDS = frozenset(('format', 'kind', 'current_candidate', 'current_version',
    'current_core', 'current_seed', 'new_seed', 'read_only', 'original_locks_held',
    'manual_only', 'workspace_enabled_env_unchanged', 'current_native_payloads_verified',
    'current_manual_helpers_reconstructed', 'derived_native_pins'))


class Stop(Exception):
    pass


def need(condition, code):
    if not condition:
        raise Stop('GO_ERP_DESKTOP_PERFORMANCE_READ_ONLY_' + code)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def module(raw, name, expected):
    need(isinstance(raw, bytes) and digest(raw) == expected, 'MODULE_HASH_CHANGED')
    value = types.ModuleType('performance_readonly_' + name)
    value.__file__ = '<pinned-performance-' + name + '>'
    sys.modules[value.__name__] = value
    exec(compile(raw, value.__file__, 'exec'), value.__dict__)
    return value


def helpers():
    need(isinstance(BUNDLED_MODULES, dict) and set(BUNDLED_MODULES) == {'payloads', 'current'}, 'BUNDLE_MISSING')
    checked = {}
    for name in ('payloads', 'current'):
        row = BUNDLED_MODULES[name]
        need(isinstance(row, (tuple, list)) and len(row) == 2, 'BUNDLE_INVALID')
        expected, encoded = row
        need(isinstance(expected, str) and re.fullmatch(r'[a-f0-9]{64}', expected)
             and isinstance(encoded, str) and len(encoded) <= 256 * 1024, 'BUNDLE_INVALID')
        try:
            raw = base64.b64decode(encoded, validate=True)
        except (TypeError, ValueError):
            raise Stop('GO_ERP_DESKTOP_PERFORMANCE_READ_ONLY_BUNDLE_INVALID') from None
        need(digest(raw) == expected, 'MODULE_HASH_CHANGED')
        checked[name] = (raw, expected)
    # Validate the complete bundle before executing either trusted module.
    result = {name: module(raw, name, expected)
              for name, (raw, expected) in checked.items()}
    return result['payloads'], result['current']


def safe_directory(path):
    info = path.lstat()
    return (stat.S_ISDIR(info.st_mode) and info.st_uid == 0
            and not info.st_mode & 0o022 and path.resolve() == path)


def original_operator():
    candidates = []
    for folder in Path('/var/tmp').glob('go-erp-shared-workspace.*'):
        try:
            candidates.append((folder.lstat().st_mtime_ns, folder))
        except OSError:
            continue
    for _mtime, folder in sorted(candidates, key=lambda item: item[0], reverse=True)[:64]:
        repository = folder / 'release.git'
        try:
            if not (safe_directory(folder) and safe_directory(repository)):
                continue
            raw = subprocess.check_output(
                ['/usr/bin/git', '--git-dir=' + str(repository), '-c', 'credential.helper=',
                 '-c', 'core.hooksPath=/dev/null', 'show',
                 ROOT_REV + ':deployment/go_erp_shared_workspace_root.py'],
                stdin=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30,
                env={'PATH': '/usr/bin:/bin', 'GIT_CONFIG_NOSYSTEM': '1',
                     'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_CONFIG_SYSTEM': '/dev/null',
                     'GIT_NO_REPLACE_OBJECTS': '1', 'GIT_NO_LAZY_FETCH': '1',
                     'GIT_OPTIONAL_LOCKS': '0', 'GIT_TERMINAL_PROMPT': '0'})
            if digest(raw) != ROOT_SHA:
                continue
        except (OSError, subprocess.SubprocessError):
            continue
        original = module(raw, 'original_root', ROOT_SHA)
        return original.Operator(original.Package(repository, ROOT_REV), original.PINS)
    raise Stop('GO_ERP_DESKTOP_PERFORMANCE_READ_ONLY_PINNED_PACKAGE_NOT_FOUND')


def public_result(value, payloads, current):
    need(isinstance(value, dict) and set(value) == PUBLIC_FIELDS, 'RESULT_FIELDS_CHANGED')
    need(type(value['format']) is int, 'RESULT_IDENTITY_CHANGED')
    expected = {'format': 1, 'kind': 'go-erp-desktop-performance-read-only-preflight',
                'current_candidate': current.CANDIDATE, 'current_version': current.VERSION,
                'current_core': current.CORE, 'current_seed': current.SEED, 'new_seed': SEED}
    need(all(value.get(name) == item for name, item in expected.items()), 'RESULT_IDENTITY_CHANGED')
    for name in PUBLIC_FIELDS - set(expected) - {'derived_native_pins'}:
        need(value[name] is True, 'RESULT_SCOPE_CHANGED')
    pins = value['derived_native_pins']
    need(isinstance(pins, dict) and set(pins) == set(payloads.CURRENT_PINS), 'RESULT_ROSTER_CHANGED')
    for row in pins.values():
        need(isinstance(row, dict) and set(row) == {'blob', 'bytes', 'sha256'}
             and isinstance(row['blob'], str) and re.fullmatch(r'[a-f0-9]{40}', row['blob'])
             and type(row['bytes']) is int and 0 < row['bytes'] <= 2 * 1024 ** 2
             and isinstance(row['sha256'], str) and re.fullmatch(r'[a-f0-9]{64}', row['sha256']),
             'RESULT_PIN_CHANGED')
    return value


def main():
    phase = 'host'
    try:
        need(os.geteuid() == 0 and socket.gethostname().split('.')[0] == 'srv1836524', 'ROOT_HOST_REQUIRED')
        need(len(sys.argv) == 1, 'ARGUMENTS_NOT_ALLOWED')
        phase = 'helpers'
        payloads, current = helpers()
        phase = 'package'
        operator = original_operator()
        expected = copy.deepcopy(payloads.CURRENT_NATIVE_HASHES)
        expected.update(NATIVE_CHANGES)
        phase = 'preflight'
        value = current.preflight(operator, payloads, seed=SEED, packaged_native_hashes=expected)
        phase = 'result'
        print(json.dumps(public_result(value, payloads, current), sort_keys=True, separators=(',', ':')))
        return 0
    except BaseException as error:
        message = str(error)
        code = message if re.fullmatch(r'GO_ERP_[A-Z0-9_]{1,170}', message) else 'GO_ERP_DESKTOP_PERFORMANCE_READ_ONLY_FAILURE'
        frames, tb = [], error.__traceback__
        while tb:
            frames.append([Path(tb.tb_frame.f_code.co_filename).name,
                           tb.tb_frame.f_code.co_name, tb.tb_lineno])
            tb = tb.tb_next
        print(json.dumps({'code': code, 'phase': phase, 'error_type': type(error).__name__,
                          'frames': frames[-8:]}, sort_keys=True, separators=(',', ':')))
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
